import numpy as np

class QuantConnectAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {
            'SPY': self.AddEquity('SPY', Resolution.Daily).Symbol,
            'AAPL': self.AddEquity('AAPL', Resolution.Daily).Symbol,
            'IBM': self.AddEquity('IBM', Resolution.Daily).Symbol,
            'BAC': self.AddEquity('BAC', Resolution.Daily).Symbol,
            'AIG': self.AddEquity('AIG', Resolution.Daily).Symbol,
        }

        self.spy_closes = []
        self.aapl_closes = []

    def OnData(self, data):
        for symbol in self.symbols.values():
            if symbol not in data:
                return

        spy_close = data[self.symbols['SPY']].Close
        aapl_close = data[self.symbols['AAPL']].Close

        self.spy_closes.append(spy_close)
        self.aapl_closes.append(aapl_close)

        if len(self.spy_closes) < 21 or len(self.aapl_closes) < 15:
            return

        if len(self.spy_closes) > 100:
            self.spy_closes.pop(0)
        if len(self.aapl_closes) > 100:
            self.aapl_closes.pop(0)

        spy_sma = np.mean(self.spy_closes[-20:])
        aapl_rsi = self._calculate_rsi(self.aapl_closes, 14)

        prev_spy_close = self.spy_closes[-2]
        prev_spy_sma = np.mean(self.spy_closes[-21:-1])

        spy_quantity = self.Portfolio[self.symbols['SPY']].Quantity
        aapl_quantity = self.Portfolio[self.symbols['AAPL']].Quantity

        if spy_quantity > 0:
            if prev_spy_close >= prev_spy_sma and spy_close < spy_sma:
                self.Sell(self.symbols['SPY'], int(spy_quantity))
        else:
            if prev_spy_close <= prev_spy_sma and spy_close > spy_sma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.4
                shares_to_buy = int(target_value / spy_close)
                if shares_to_buy > 0:
                    self.Buy(self.symbols['SPY'], shares_to_buy)

        if aapl_quantity > 0:
            if aapl_rsi > 60:
                self.Sell(self.symbols['AAPL'], int(aapl_quantity))
        else:
            if self._is_red_for_n_days(self.aapl_closes, 3):
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.Buy(self.symbols['AAPL'], shares_to_buy)

    def _is_red_for_n_days(self, closes, n):
        if len(closes) < n + 1:
            return False
        for i in range(len(closes) - n, len(closes)):
            if closes[i] >= closes[i - 1]:
                return False
        return True

    def _calculate_rsi(self, closes, period):
        if len(closes) < period + 1:
            return 50

        recent_closes = closes[-(period + 1):]
        gains = 0
        losses = 0

        for i in range(1, len(recent_closes)):
            change = recent_closes[i] - recent_closes[i - 1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

