class LeanAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for ticker in self.tickers:
            self.AddEquity(ticker, Resolution.Daily)

        self.spy_sma = SimpleMovingAverage(20)
        self.aapl_rsi = RelativeStrengthIndex(14)

        self.prev_spy_close = None
        self.prev_aapl_close = None
        self.consecutive_red_days = 0

    def OnData(self, data):
        for ticker in self.tickers:
            if not data.ContainsKey(ticker):
                return

        spy_bar = data["SPY"]
        aapl_bar = data["AAPL"]

        self.spy_sma.Update(spy_bar)
        self.aapl_rsi.Update(aapl_bar)

        if self.prev_aapl_close is None:
            self.prev_aapl_close = aapl_bar.Close
            self.prev_spy_close = spy_bar.Close
            return

        if aapl_bar.Close < self.prev_aapl_close:
            self.consecutive_red_days += 1
        else:
            self.consecutive_red_days = 0

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            self.prev_spy_close = spy_bar.Close
            self.prev_aapl_close = aapl_bar.Close
            return

        spy_qty = self.Portfolio["SPY"].Quantity
        aapl_qty = self.Portfolio["AAPL"].Quantity

        if spy_qty > 0:
            if self.prev_spy_close > self.spy_sma.Current.Value and spy_bar.Close <= self.spy_sma.Current.Value:
                self.MarketOrder("SPY", -spy_qty)

        if spy_qty == 0:
            if self.prev_spy_close <= self.spy_sma.Current.Value and spy_bar.Close > self.spy_sma.Current.Value:
                invest_value = self.Portfolio.TotalPortfolioValue * 0.40
                shares = int(invest_value / spy_bar.Close)
                if shares > 0:
                    self.MarketOrder("SPY", shares)

        if aapl_qty > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.MarketOrder("AAPL", -aapl_qty)

        if aapl_qty == 0:
            if self.consecutive_red_days >= 3:
                if self.Portfolio.Cash >= 20000:
                    shares = int(20000 / aapl_bar.Close)
                    if shares > 0:
                        self.MarketOrder("AAPL", shares)

        self.prev_spy_close = spy_bar.Close
        self.prev_aapl_close = aapl_bar.Close

