        self.aapl_closes.append(aapl_close)

        if len(self.spy_closes) <= self.spy_sma_period:
            return
        if len(self.aapl_closes) < self.aapl_rsi_period + 1:
            return

        spy_sma = np.mean(self.spy_closes[-self.spy_sma_period:])
        aapl_rsi = self.calculate_rsi(self.aapl_closes, self.aapl_rsi_period)

        if aapl_close < self.aapl_closes[-2]:
            self.aapl_red_count += 1
        else:
            self.aapl_red_count = 0

        spy_qty = self.Portfolio[self.symbols["SPY"]].Quantity
        aapl_qty = self.Portfolio[self.symbols["AAPL"]].Quantity

        if spy_qty > 0:
            if self.spy_prev_sma is not None and self.spy_prev_close >= self.spy_prev_sma and spy_close < spy_sma:
                self.MarketOrder(self.symbols["SPY"], -spy_qty)
        else:
            if self.spy_prev_sma is not None and self.spy_prev_close <= self.spy_prev_sma and spy_close > spy_sma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                invest_amount = portfolio_value * 0.4
                shares_to_buy = int(invest_amount / spy_close)
                if shares_to_buy > 0:
                    self.MarketOrder(self.symbols["SPY"], shares_to_buy)

        if aapl_qty > 0:
            if aapl_rsi > 60:
                self.MarketOrder(self.symbols["AAPL"], -aapl_qty)
        else:
            if self.aapl_red_count >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.MarketOrder(self.symbols["AAPL"], shares_to_buy)

        self.spy_prev_close = spy_close
        self.spy_prev_sma = spy_sma

    def calculate_rsi(self, closes, period):
        if len(closes) < period + 1:
            return None

        gains = 0.0
        losses = 0.0
        for i in range(-period, 0):
            change = closes[i] - closes[i-1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100.0 if avg_gain > 0 else 0.0

        rs = avg_gain / avg_loss
        rsi = 100.0 - (100.0 / (1.0 + rs))

        return rsi

