            return

        spy_today = self.spy_prices[-1]
        spy_yesterday = self.spy_prices[-2]
        aapl_today = self.aapl_prices[-1]
        aapl_yesterday = self.aapl_prices[-2]

        spy_sma_today = sum(self.spy_prices[-self.spy_sma_period:]) / self.spy_sma_period
        spy_sma_yesterday = sum(self.spy_prices[-self.spy_sma_period-1:-1]) / self.spy_sma_period

        aapl_red_count = 0
        for i in range(len(self.aapl_prices) - 1, 0, -1):
            if self.aapl_prices[i] < self.aapl_prices[i-1]:
                aapl_red_count += 1
            else:
                break

        aapl_rsi = self._calc_rsi(self.aapl_prices, 14)

        spy_qty = self.Portfolio["SPY"].Quantity
        aapl_qty = self.Portfolio["AAPL"].Quantity

        if spy_qty > 0:
            if spy_yesterday >= spy_sma_yesterday and spy_today < spy_sma_today:
                self.Liquidate("SPY")

        if aapl_qty > 0:
            if aapl_rsi > 60:
                self.Liquidate("AAPL")

        if spy_qty == 0:
            if spy_yesterday <= spy_sma_yesterday and spy_today > spy_sma_today:
                portfolio_val = self.Portfolio.TotalPortfolioValue
                target_val = portfolio_val * 0.4
                qty = int(target_val / spy_today)
                if qty > 0:
                    self.Buy("SPY", qty)

        if aapl_qty == 0:
            if aapl_red_count >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    qty = int(20000 / aapl_today)
                    if qty > 0:
                        self.Buy("AAPL", qty)

    def _calc_rsi(self, prices, period):
        if len(prices) < period + 1:
            return 50

        gain = 0
        loss = 0
        for i in range(len(prices) - period, len(prices)):
            delta = prices[i] - prices[i-1]
            if delta > 0:
                gain += delta
            else:
                loss -= delta

        avg_gain = gain / period
        avg_loss = loss / period

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

