class QuantConnectLEANAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        # Subscribe to equities
        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        # Indicators
        self.spy_sma = self.SMA(self.symbols["SPY"], 50, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.symbols["AAPL"], 14, Resolution.Daily)

        # Previous values for cross detection
        self.spy_prev_close = None
        self.spy_prev_sma = None

        # Red days counter
        self.aapl_consecutive_reds = 0
        self.aapl_prev_close = None

    def OnData(self, data):
        # Check if all tickers have data
        for ticker in self.tickers:
            if self.symbols[ticker] not in data:
                return

        # Check if indicators are ready
        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        # Get current values
        spy_close = data[self.symbols["SPY"]].Close
        spy_sma = self.spy_sma.Current.Value

        aapl_close = data[self.symbols["AAPL"]].Close
        aapl_rsi = self.aapl_rsi.Current.Value

        # Get current positions
        spy_quantity = self.Portfolio[self.symbols["SPY"]].Quantity
        aapl_quantity = self.Portfolio[self.symbols["AAPL"]].Quantity

        # Strategy A: SPY SMA Crossover
        if spy_quantity > 0:
            # Evaluate sell: close crosses below SMA
            if self.spy_prev_close is not None:
                if self.spy_prev_close >= self.spy_prev_sma and spy_close < spy_sma:
                    self.MarketOrder(self.symbols["SPY"], -spy_quantity)

        if spy_quantity == 0:
            # Evaluate buy: close crosses above SMA
            if self.spy_prev_close is not None:
                if self.spy_prev_close <= self.spy_prev_sma and spy_close > spy_sma:
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    invest_amount = portfolio_value * 0.4
                    shares = int(invest_amount / spy_close)
                    if shares > 0:
                        self.MarketOrder(self.symbols["SPY"], shares)

        # Strategy B: AAPL Red Days / RSI
        if self.aapl_prev_close is not None:
            if aapl_close < self.aapl_prev_close:
                self.aapl_consecutive_reds += 1
            else:
                self.aapl_consecutive_reds = 0

        if aapl_quantity > 0:
            # Evaluate sell: RSI > 60
            if aapl_rsi > 60:
                self.MarketOrder(self.symbols["AAPL"], -aapl_quantity)

        if aapl_quantity == 0:
            # Evaluate buy: red for 3 consecutive days
            if self.aapl_consecutive_reds >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.symbols["AAPL"], shares)

        # Update previous values
        self.spy_prev_close = spy_close
        self.spy_prev_sma = spy_sma
        self.aapl_prev_close = aapl_close

