        self.spy_closes.append(data["SPY"].Close)
        self.aapl_closes.append(data["AAPL"].Close)

        if len(self.aapl_closes) >= 2:
            if self.aapl_closes[-1] < self.aapl_closes[-2]:
                self.aapl_consecutive_red += 1
            else:
                self.aapl_consecutive_red = 0

        if len(self.spy_closes) >= self.spy_sma_period + 1:
            self.EvaluateStrategyA()

        if len(self.aapl_closes) >= 15:
            self.EvaluateStrategyB()

    def EvaluateStrategyA(self):
        closes = self.spy_closes[-(self.spy_sma_period + 1):]
        prev_sma = sum(closes[:-1]) / self.spy_sma_period
        curr_sma = sum(closes[1:]) / self.spy_sma_period
        prev_close = closes[-2]
        curr_close = closes[-1]

        if self.spy_lot > 0:
            if prev_close >= prev_sma and curr_close < curr_sma:
                self.Sell("SPY", self.spy_lot)
                self.spy_lot = 0

        if self.spy_lot == 0:
            if prev_close <= prev_sma and curr_close > curr_sma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                investment = portfolio_value * 0.4
                shares = int(investment / curr_close)
                if shares > 0:
                    self.Buy("SPY", shares)
                    self.spy_lot = shares

    def EvaluateStrategyB(self):
        curr_close = self.aapl_closes[-1]

        if self.aapl_lot > 0:
            rsi = self.CalculateRSI()
            if rsi > 60:
                self.Sell("AAPL", self.aapl_lot)
                self.aapl_lot = 0

        if self.aapl_lot == 0:
            if self.aapl_consecutive_red >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares = int(20000 / curr_close)
                    if shares > 0:
                        self.Buy("AAPL", shares)
                        self.aapl_lot = shares

    def CalculateRSI(self):
        if len(self.aapl_closes) < 15:
            return 50.0

        closes = self.aapl_closes[-15:]
        gains = 0.0
        losses = 0.0

        for i in range(1, 15):
            change = closes[i] - closes[i-1]
            if change > 0:
                gains += change
            else:
                losses += abs(change)

        avg_gain = gains / 14.0
        avg_loss = losses / 14.0

        if avg_loss == 0:
            return 100.0

        rs = avg_gain / avg_loss
        rsi = 100.0 - (100.0 / (1.0 + rs))
        return rsi

