class MyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.data = {}

        for symbol in self.symbols:
            self.AddEquity(symbol, Resolution.Daily)
            self.data[symbol] = SymbolData(self, symbol)

        self.strategy_a = StrategyA(self)
        self.strategy_b = StrategyB(self)

    def OnData(self, data):
        for symbol in self.symbols:
            if symbol not in data or data[symbol] is None:
                return

        for symbol in self.symbols:
            self.data[symbol].update(data[symbol])

        self.strategy_a.evaluate_and_trade()
        self.strategy_b.evaluate_and_trade()


class SymbolData:
    def __init__(self, algorithm, symbol):
        self.algorithm = algorithm
        self.symbol = symbol
        self.closes = []
        self.sma_values = []
        self.rsi = RelativeStrengthIndex(14)

    def update(self, bar):
        self.closes.append(bar.Close)

        if len(self.closes) >= 20:
            sma = sum(self.closes[-20:]) / 20.0
            self.sma_values.append(sma)
        else:
            self.sma_values.append(None)

        self.rsi.Update(bar.Close)

    def is_sma_ready(self):
        return len(self.closes) >= 20

    def is_rsi_ready(self):
        return len(self.closes) >= 14 and self.rsi.IsReady

    def closes_crosses_above_sma(self):
        if len(self.closes) < 2 or len(self.sma_values) < 2:
            return False

        prev_sma = self.sma_values[-2]
        curr_sma = self.sma_values[-1]

        if prev_sma is None or curr_sma is None:
            return False

        return (self.closes[-2] <= prev_sma) and (self.closes[-1] > curr_sma)

    def closes_crosses_below_sma(self):
        if len(self.closes) < 2 or len(self.sma_values) < 2:
            return False

        prev_sma = self.sma_values[-2]
        curr_sma = self.sma_values[-1]

        if prev_sma is None or curr_sma is None:
            return False

        return (self.closes[-2] >= prev_sma) and (self.closes[-1] < curr_sma)

    def count_consecutive_red_days(self):
        count = 0
        for i in range(len(self.closes) - 1, 0, -1):
            if self.closes[i] < self.closes[i - 1]:
                count += 1
            else:
                break
        return count

    def get_rsi(self):
        return self.rsi.Current.Value if self.rsi.IsReady else None

    def get_close(self):
        return self.closes[-1] if self.closes else None


class StrategyA:
    def __init__(self, algorithm):
        self.algorithm = algorithm
        self.symbol = "SPY"
        self.lot_shares = 0

    def is_ready(self):
        return self.algorithm.data[self.symbol].is_sma_ready()

    def evaluate_and_trade(self):
        if not self.is_ready():
            return

        if self.lot_shares > 0:
            if self.should_sell():
                self.sell_all()

        if self.lot_shares == 0:
            if self.should_buy():
                self.buy()

    def should_buy(self):
        return self.algorithm.data[self.symbol].closes_crosses_above_sma()

    def should_sell(self):
        return self.algorithm.data[self.symbol].closes_crosses_below_sma()

    def buy(self):
        data = self.algorithm.data[self.symbol]
        portfolio_value = self.algorithm.Portfolio.TotalPortfolioValue
        amount = portfolio_value * 0.4
        close = data.get_close()
        shares = int(amount / close)
        if shares > 0:
            self.algorithm.MarketOrder(self.symbol, shares)
            self.lot_shares = shares

    def sell_all(self):
        if self.lot_shares > 0:
            self.algorithm.MarketOrder(self.symbol, -self.lot_shares)
            self.lot_shares = 0


class StrategyB:
    def __init__(self, algorithm):
        self.algorithm = algorithm
        self.symbol = "AAPL"
        self.lot_shares = 0

    def is_ready(self):
        return self.algorithm.data[self.symbol].is_rsi_ready()

    def evaluate_and_trade(self):
        if not self.is_ready():
            return

        if self.lot_shares > 0:
            if self.should_sell():
                self.sell_all()

        if self.lot_shares == 0:
            if self.should_buy():
                self.buy()

    def should_buy(self):
        data = self.algorithm.data[self.symbol]
        return data.count_consecutive_red_days() >= 3

    def should_sell(self):
        data = self.algorithm.data[self.symbol]
        rsi = data.get_rsi()
        return rsi is not None and rsi > 60

    def buy(self):
        available_cash = self.algorithm.Portfolio.Cash
        if available_cash >= 20000:
            data = self.algorithm.data[self.symbol]
            close = data.get_close()
            shares = int(20000 / close)
            if shares > 0:
                self.algorithm.MarketOrder(self.symbol, shares)
                self.lot_shares = shares

    def sell_all(self):
        if self.lot_shares > 0:
            self.algorithm.MarketOrder(self.symbol, -self.lot_shares)
            self.lot_shares = 0

