    def update(self, bar):
        self.closes.append(bar.Close)

        if len(self.closes) >= 20:
            sma = sum(self.closes[-20:]) / 20.0
            self.sma_values.append(sma)
        else:
            self.sma_values.append(None)

        self.rsi.Update(bar.Close)

    def is_sma_ready(self):
        return len(self.closes) >= 20

    def is_rsi_ready(self):
        return len(self.closes) >= 14 and self.rsi.IsReady

    def closes_crosses_above_sma(self):
        if len(self.closes) < 2 or len(self.sma_values) < 2:
            return False

        prev_sma = self.sma_values[-2]
        curr_sma = self.sma_values[-1]

        if prev_sma is None or curr_sma is None:
            return False

        return (self.closes[-2] <= prev_sma) and (self.closes[-1] > curr_sma)

    def closes_crosses_below_sma(self):
        if len(self.closes) < 2 or len(self.sma_values) < 2:
            return False

        prev_sma = self.sma_values[-2]
        curr_sma = self.sma_values[-1]

        if prev_sma is None or curr_sma is None:
            return False

        return (self.closes[-2] >= prev_sma) and (self.closes[-1] < curr_sma)

    def count_consecutive_red_days(self):
        count = 0
        for i in range(len(self.closes) - 1, 0, -1):
            if self.closes[i] < self.closes[i - 1]:
                count += 1
            else:
                break
        return count

    def get_rsi(self):
        return self.rsi.Current.Value if self.rsi.IsReady else None

    def get_close(self):
        return self.closes[-1] if self.closes else None


