                self.aapl_red_count += 1
            else:
                self.aapl_red_count = 0

        aapl_rsi = self._calculate_rsi(self.closes['AAPL'][-14:])

        spy_quantity = self.Portfolio[self.symbols['SPY']].Quantity
        aapl_quantity = self.Portfolio[self.symbols['AAPL']].Quantity

        if spy_quantity > 0:
            if spy_close_yesterday > spy_sma_yesterday and spy_close_today <= spy_sma_today:
                self.MarketOrder(self.symbols['SPY'], -spy_quantity)
        elif spy_quantity == 0:
            if spy_close_yesterday <= spy_sma_yesterday and spy_close_today > spy_sma_today:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                investment_amount = portfolio_value * 0.4
                shares_to_buy = int(investment_amount / spy_close_today)
                if shares_to_buy > 0:
                    self.MarketOrder(self.symbols['SPY'], shares_to_buy)

        if aapl_quantity > 0:
            if aapl_rsi > 60:
                self.MarketOrder(self.symbols['AAPL'], -aapl_quantity)
        elif aapl_quantity == 0:
            if self.aapl_red_count >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close_today)
                    if shares_to_buy > 0:
                        self.MarketOrder(self.symbols['AAPL'], shares_to_buy)

    def _calculate_rsi(self, closes):
        if len(closes) < 2:
            return None

        n = len(closes)
        gains = 0
        losses = 0

        for i in range(1, n):
            change = closes[i] - closes[i-1]
            if change > 0:
                gains += change
            else:
                losses += abs(change)

        avg_gain = gains / n
        avg_loss = losses / n

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 0

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))

        return rsi

    def _count_consecutive_red_days(self, closes):
        count = 0
        for i in range(len(closes)-1, 0, -1):
            if closes[i] < closes[i-1]:
                count += 1
            else:
                break
        return count

