                    if shares_to_buy > 0:
                        self.MarketOrder(self.strategy_a_symbol, shares_to_buy)
                        self.strategy_a_lot = shares_to_buy

        if len(self.strategy_b_aapl_closes) >= 14:
            aapl_rsi = self.calculate_rsi(self.strategy_b_aapl_closes[-14:])
