        if len(prices) < 14:
            return 50

        prices = prices[-14:]
        gains = 0
        losses = 0

        for i in range(1, len(prices)):
            change = prices[i] - prices[i-1]
            if change > 0:
                gains += change
            else:
                losses -= change

        avg_gain = gains / 14
        avg_loss = losses / 14

        if avg_loss == 0:
            return 100

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
