class QuantConnectLEANAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.price_data = {sym: [] for sym in self.symbols}

        for symbol in self.symbols:
            self.AddEquity(symbol, Resolution.Daily)

    def OnData(self, data):
        for symbol in self.symbols:
            if symbol not in data or data[symbol] is None:
                return

        for symbol in self.symbols:
            self.price_data[symbol].append(data[symbol].Close)

        if len(self.price_data['SPY']) < 101:
            return

        spy_closes = self.price_data['SPY']
        aapl_closes = self.price_data['AAPL']

        sma_100 = sum(spy_closes[-100:]) / 100
        sma_100_prev = sum(spy_closes[-101:-1]) / 100

        red_days = 0
        for i in range(len(aapl_closes) - 1, 0, -1):
            if aapl_closes[i] < aapl_closes[i - 1]:
                red_days += 1
            else:
                break

        rsi_14 = self.calculate_rsi(aapl_closes, 14)

        spy_close = spy_closes[-1]
        spy_close_prev = spy_closes[-2]

        spy_quantity = self.Portfolio['SPY'].Quantity
        aapl_quantity = self.Portfolio['AAPL'].Quantity

        if spy_quantity > 0:
            if spy_close_prev >= sma_100_prev and spy_close < sma_100:
                self.Sell('SPY', int(spy_quantity))

        if aapl_quantity > 0:
            if rsi_14 is not None and rsi_14 > 60:
                self.Sell('AAPL', int(aapl_quantity))

        if spy_quantity == 0:
            if spy_close_prev <= sma_100_prev and spy_close > sma_100:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                shares_to_buy = int(portfolio_value * 0.4 / spy_close)
                if shares_to_buy > 0:
                    self.Buy('SPY', shares_to_buy)

        if aapl_quantity == 0:
            if red_days >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / aapl_closes[-1])
                    if shares_to_buy > 0:
                        self.Buy('AAPL', shares_to_buy)

    def calculate_rsi(self, closes, period):
        if len(closes) < period + 1:
            return None

        recent = closes[-(period + 1):]
        gains = 0
