            return False
        return prices[-2] <= level and prices[-1] > level

    def crosses_below(self, prices, level):
        if len(prices) < 2:
            return False
        return prices[-2] >= level and prices[-1] < level

    def is_red_n_days(self, prices, n):
        if len(prices) < n + 1:
            return False
        for i in range(-n, 0):
            if prices[i] >= prices[i-1]:
                return False
        return True

