import numpy as np

class QuantConnectLEANAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for symbol in self.symbols:
            self.AddEquity(symbol, Resolution.Daily)

        self.history = {symbol: {'close': []} for symbol in self.symbols}

    def OnData(self, data):
        for symbol in self.symbols:
            if symbol not in data:
                return

        for symbol in self.symbols:
            self.history[symbol]['close'].append(data[symbol].Close)

        if len(self.history['SPY']['close']) < 101:
            return

        self._execute_strategy_a(data)
        self._execute_strategy_b(data)

    def _execute_strategy_a(self, data):
        spy_close = data['SPY'].Close
        spy_holdings = self.Portfolio['SPY'].Quantity

        closes = self.history['SPY']['close']
        ma_100_today = np.mean(closes[-100:])
        ma_100_yesterday = np.mean(closes[-101:-1])
        prev_close = closes[-2]

        if spy_holdings > 0:
            if prev_close >= ma_100_yesterday and spy_close < ma_100_today:
                self.Liquidate('SPY')

        if spy_holdings == 0:
            if prev_close <= ma_100_yesterday and spy_close > ma_100_today:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                amount = portfolio_value * 0.40
                shares = int(amount / spy_close)
                if shares > 0:
                    self.Buy('SPY', shares)

    def _execute_strategy_b(self, data):
        aapl_close = data['AAPL'].Close
        aapl_holdings = self.Portfolio['AAPL'].Quantity

        closes = self.history['AAPL']['close']

        red_streak = 0
        for i in range(len(closes) - 1, 0, -1):
